public class KeypadTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String buttonText(javax.swing.JPanel panel, int index) {
        if (index >= panel.getComponentCount()) {
            return "(missing)";
        }
        java.awt.Component c = panel.getComponent(index);
        if (!(c instanceof javax.swing.JButton)) {
            return "(not a JButton)";
        }
        return ((javax.swing.JButton) c).getText();
    }

    public static void main(String[] args) {
        try {
            Keypad pad = new Keypad();
            java.awt.LayoutManager lm = pad.getLayout();
            check("grid has 4 rows", 4,
                    lm instanceof java.awt.GridLayout ? ((java.awt.GridLayout) lm).getRows() : -1);
            check("grid has 3 columns", 3,
                    lm instanceof java.awt.GridLayout ? ((java.awt.GridLayout) lm).getColumns() : -1);
            check("twelve buttons added", 12, pad.getComponentCount());
            check("first key", "1", buttonText(pad, 0));
            check("middle key", "5", buttonText(pad, 4));
            check("star key", "*", buttonText(pad, 9));
            check("zero key", "0", buttonText(pad, 10));
            check("hash key", "#", buttonText(pad, 11));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

