import java.awt.GridLayout;
import javax.swing.JButton;
import javax.swing.JPanel;

public class Keypad extends JPanel {

    private static final String[] KEYS = {
        "1", "2", "3", "4", "5", "6", "7", "8", "9", "*", "0", "#"
    };

    public Keypad() {
        setLayout(new GridLayout(4, 3));
        for (String key : KEYS) {
            add(new JButton(key));
        }
    }
}
